// Generated by AI
import { describe, expect, it } from 'vitest';
import { parseSessionEvent, type SessionEvent } from '@felan-ai/session-protocol';
import { createSessionState, reduceSession } from '../src/client/reducer.js';
import { delta, snapshot } from './client-fixtures.js';

const event = (rev: number, change: unknown): SessionEvent => parseSessionEvent({ v: 1, session: 'session', rev, change });
const live = () => reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: snapshot() });

describe('declarative session reducer', () => {
  it('converges on duplicates, unknown additions and coalesced tool replacements', () => {
    const tool = { id: 'tool', name: 'read', message: 'message', state: 'running', output: 'a', truncated: false };
    const events = [event(1, { type: 'future.optional', data: true }), event(2, { type: 'tool.updated', tool }),
      event(3, { type: 'tool.updated', tool: { ...tool, state: 'completed', output: 'abc' } })];
    const run = (duplicates: boolean) => events.flatMap(value => duplicates ? [value, value] : [value]).reduce(
      (state, value) => reduceSession(state, { type: 'update', update: value }), live());
    expect(run(true)).toEqual(run(false));
    expect(run(true).snapshot?.tools).toEqual([{ ...tool, state: 'completed', output: 'abc' }]);
  });
  it('buffers out-of-order and missing revisions and recovers at an atomic snapshot', () => {
    const late = event(3, { type: 'model.updated', model: { provider: 'fixture', id: 'new' }, thinking: 'high' });
    let state = reduceSession(live(), { type: 'update', update: late });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'update', update: event(2, { type: 'future.optional' }) });
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(2) });
    expect(state.status).toBe('live');
    expect(state.snapshot?.revision).toBe(3);
    expect(state.snapshot?.thinking).toBe('high');
  });
  it('reconstructs a snapshot/live race using both revision and independent Unicode offsets', () => {
    let state = createSessionState('session');
    state = reduceSession(state, { type: 'update', update: delta('😀', 1) });
    state = reduceSession(state, { type: 'update', update: delta('思', 0, 'thinking') });
    const cut = snapshot(); cut.activeStreams = [{ id: 'assistant', message: 'message', kind: 'assistant', text: 'A', offset: 1 }];
    state = reduceSession(state, { type: 'snapshot', snapshot: cut });
    state = reduceSession(state, { type: 'update', update: delta('😀', 1) });
    state = reduceSession(state, { type: 'update', update: delta('考', 1, 'thinking') });
    expect(state.snapshot?.activeStreams.map(stream => [stream.kind, stream.text, stream.offset])).toEqual([['assistant', 'A😀', 2], ['thinking', '思考', 2]]);
  });
  it('starts an absent prefix only at zero; recovers a gap once then waits for completion', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('missing', 4) });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot() });
    expect(state.status).toBe('live');
    expect(state.snapshot?.completionOnlyStreams[0]?.id).toBe('assistant');
    state = reduceSession(state, { type: 'update', update: delta('ignore', 0) });
    expect(state.snapshot?.activeStreams).toEqual([]);
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'message.completed', message: {
      id: 'message', entryId: 'entry', role: 'assistant', timestamp: 1, content: [{ type: 'text', text: 'authoritative' }],
    } }) });
    state = reduceSession(state, { type: 'update', update: delta('late', 0) });
    expect(state.snapshot?.completionOnlyStreams).toEqual([]);
    expect(state.snapshot?.activeStreams).toEqual([]);
    expect(state.snapshot?.history.entries[0]?.content).toEqual([{ type: 'text', text: 'authoritative' }]);
  });
  it('accepts a recovered prefix, but ignores explicitly completion-only streams', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('✓', 2) });
    const cut = snapshot(); cut.activeStreams = [{ id: 'assistant', message: 'message', kind: 'assistant', text: 'A😀', offset: 2 }];
    state = reduceSession(state, { type: 'snapshot', snapshot: cut });
    expect(state.snapshot?.activeStreams[0]?.text).toBe('A😀✓');
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'stream.completion_only', stream: { id: 'assistant', message: 'message', kind: 'assistant', reason: 'limit' } }) });
    state = reduceSession(state, { type: 'update', update: delta('ignored', 3) });
    expect(state.snapshot?.completionOnlyStreams[0]?.reason).toBe('limit');
    expect(state.snapshot?.activeStreams).toEqual([]);
  });
  it('never applies a delta for a different message while a message is open', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('open') });
    state = reduceSession(state, { type: 'update', update: delta('wrong', 0, 'thinking', 'other') });
    expect(state.status).toBe('recovering');
    expect(state.snapshot?.activeStreams.map(stream => stream.text)).toEqual(['open']);
  });
  it('bounds buffered events and recovery attempts without fabricating revisions', () => {
    let state = live();
    for (let i = 0; i < 1030; i++) state = reduceSession(state, { type: 'update', update: event(10, { type: 'future.optional' }) });
    expect(state.buffered.length).toBeLessThanOrEqual(1024);
    expect(state.snapshot?.revision).toBe(0);
    for (let i = 0; i < 4; i++) state = reduceSession(state, { type: 'recovery_started' });
    expect(state.status).toBe('blocked');
  });
  it('retains overflow invalidation until a snapshot requested after the loss', () => {
    let state = live();
    const requestedGeneration = state.bufferGeneration;
    for (let rev = 2; rev < 1030; rev++) state = reduceSession(state, { type: 'update', update: event(rev, { type: 'future.optional' }) });
    expect(state.bufferGeneration).toBeGreaterThan(requestedGeneration);
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1029), bufferGeneration: requestedGeneration });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1029), bufferGeneration: state.bufferGeneration });
    expect(state.status).toBe('live'); expect(state.snapshot?.revision).toBe(1029);
  });
  it('rejects regressive and cross-session snapshots and keeps disconnect distinct from cancellation', () => {
    let state = reduceSession(live(), { type: 'snapshot', snapshot: snapshot(2) });
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1) });
    expect(state.status).toBe('recovering'); expect(state.snapshot?.revision).toBe(2);
    expect(() => reduceSession(state, { type: 'snapshot', snapshot: { ...snapshot(), session: 'other' } })).toThrow(/mismatch/);
    const running = snapshot(); running.run = { state: 'running', id: 'run' };
    state = reduceSession(live(), { type: 'snapshot', snapshot: running });
    state = reduceSession(state, { type: 'disconnected' });
    expect(state.snapshot?.run).toEqual({ state: 'running', id: 'run' });
  });
});
